def S(N):
    total_sum = 0
    for a in range(1, N + 1):
        for b in range(1, N + 1):
            total_sum += (a * b) // (N + 1)
    return total_sum

def T(N):
    return (N**3 - N**2 + 2) / 4

results = {}
for N in [1, 2, 3, 4]:
    s_n = S(N)
    t_n = T(N)
    results[N] = {'S(N)': s_n, 'T(N)': t_n}

print(results)

